{"command":"cat <<'EOF' > entr.c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    const char *release = "release: 5.7";
    const char *usage = "usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames";
    const char *hint = "hint: use -h to display option summary";

    // Special -h long help
    if (argc > 1) {
        for (int i = 1; i < argc; ++i) {
            if (strcmp(argv[i], "-h") == 0) {
                printf("%s\n", release);
                printf("%s\n", usage);
                printf("summary:\n");
                printf("    -a  Do not consolidate events\n");
                printf("    -c  Clear screen before execution\n");
                printf("    -d  Track files added or removed from directories\n");
                printf("    -n  Non-interactive mode\n");
                printf("    -p  Wait for first event\n");
                printf("    -r  Run as a background process, use signal to restart\n");
                printf("    -s  Evaluate using a shell\n");
                printf("    -x  Format exit status\n");
                printf("    -z  Exit after the utility completes\n");
                printf("docs:\n");
                printf("    man entr\n");
                return 0;
            }
        }
        // If any arg starts with "--" produce invalid option like original
        for (int i = 1; i < argc; ++i) {
            if (argv[i][0] == '-' && argv[i][1] == '-') {
                // print invalid option with the second char shown as '-'
                printf("%s: invalid option -- '%c'\n", argv[0], argv[i][1]);
                printf("%s\n", release);
                printf("%s\n", usage);
                printf("%s\n", hint);
                return 0;
            }
        }
        // Otherwise print usage+hint and exit 0
        printf("%s\n", release);
        printf("%s\n", usage);
        printf("%s\n", hint);
        return 0;
    }

    // No args
    printf("%s\n", release);
    printf("%s\n", usage);
    printf("%s\n", hint);
    return 1;
}
EOF

cat <<'EOF' > compile.sh
#!/bin/sh
set -e
cc -O2 -s entr.c -o executable
chmod +x ./executable
EOF

cat <<'EOF' > .gitignore
executable
EOF

chmod +x compile.sh

# Build to verify
./compile.sh

# Test basic behaviors
echo '--- NO ARGS ---'
./executable || echo rc:$?

echo '--- -h ---'
./executable -h || echo rc:$?

echo '--- --help ---'
./executable --help || echo rc:$?

echo '--- -a ---'
./executable -a || echo rc:$?
EOF"}

